// Builds the served page from index.src.html: its stylesheets joined into app.bundle.css, its scripts joined into
// app.bundle.js (same order), and index.html loading just those two. Run after changing any page file:
//   node scripts/build-bundle.mjs
// Why: Chromium's preload scanner stops at the page's CSP <meta>, so ~60 separate scripts were fetched one after
// another, a full round trip each. tests/bundle.test.mjs fails while the committed output is stale.
import {readFileSync,writeFileSync} from 'node:fs';import {createHash} from 'node:crypto';import {fileURLToPath} from 'node:url';
const linkTag=/<link rel="stylesheet" href="([^"]+)">/g,scriptTag=/<script src="([^"]+)"><\/script>/g;
const local=href=>href.split('?')[0];
// Joined text must behave like the separate files: every page script already runs in strict mode except the vendor
// libraries (strict inside their own wrappers) and two plain assignments, so the bundle is strict as a whole. The
// separator ends any statement a file leaves open. A source map comment would point at the wrong file, so it goes.
export function joinScripts(files){
 const later=laterLexicalNames(files);
 return "'use strict';\n// Generated by scripts/build-bundle.mjs from index.src.html. Edit the source files, then rebuild.\n"
  +files.map(({name,text},i)=>`;// ${name}\n${guardTypeof(text.replace(/^\/\/# sourceMappingURL=.*$/m,''),later[i]).replace(/\s+$/,'')}\n`).join('');
}
// As separate scripts, `typeof x` for a let/const/class of a file further down the page gave 'undefined' while the
// page loaded (x did not exist yet). In one script x exists but is uninitialised and typeof throws, which would stop
// every file after it. Those tests are rewritten to give 'undefined' until x is set, as before.
function guardTypeof(text,names){
 if(!names.size)return text;
 return text.replace(/\btypeof\s+([A-Za-z_$][\w$]*)(?![\w$]|\s*(?:[.[(]|\?\.))/g,(match,name)=>names.has(name)?`(()=>{try{return typeof ${name}}catch{return 'undefined'}})()`:match);
}
// For each file, the top-level let/const/class names of the files after it (none for vendor files). Names come from
// declarations that start a line; a name read by mistake is harmless, its rewrite gives the same answer.
function laterLexicalNames(files){
 const own=files.map(({name,text})=>{
  const names=new Set();if(name.startsWith('vendor/'))return names;
  for(const [,rest] of text.matchAll(/^(?:let|const|class)\s+(.*)$/gm)){
   let depth=0,next=true;
   for(const [token] of rest.matchAll(/[A-Za-z_$][\w$]*|\S/g)){
    if('([{'.includes(token))depth++;else if(')]}'.includes(token))depth--;
    else if(!depth&&token===';')break;else if(!depth&&token===',')next=true;
    else if(next&&!depth){if(/^[A-Za-z_$]/.test(token))names.add(token);next=false;}
   }
  }
  return names;
 });
 return files.map(({name},i)=>new Set(name.startsWith('vendor/')?[]:own.slice(i+1).flatMap(set=>[...set])));
}
function joinStyles(read,files){return '/* Generated by scripts/build-bundle.mjs from index.src.html. Edit the source files, then rebuild. */\n'+files.map(f=>`/* ${f} */\n${read(f).replace(/\s+$/,'')}\n`).join('');}
const hash=text=>createHash('sha256').update(text).digest('hex').slice(0,12);
export function build(root=fileURLToPath(new URL('..',import.meta.url))){
 const read=f=>readFileSync(new URL(f,'file://'+root.replace(/\/?$/,'/')),'utf8').replace(/\r\n/g,'\n');
 const page=read('index.src.html'),styles=[...page.matchAll(linkTag)].map(m=>local(m[1])),scripts=[...page.matchAll(scriptTag)].map(m=>local(m[1]));
 if(!styles.length||!scripts.length)throw Error('index.src.html lists no stylesheets or scripts');
 if(/<script|stylesheet/.test(page.replace(linkTag,'').replace(scriptTag,'')))throw Error('index.src.html has a script or stylesheet tag the build does not understand');
 const css=joinStyles(read,styles),js=joinScripts(scripts.map(name=>({name,text:read(name)})));
 // The Supabase connection is set up while the bundle downloads instead of after it runs.
 const api=read('config.js').match(/url:'(https:\/\/[a-z0-9-]+\.supabase\.co)'/)?.[1];
 let first=true,html=page.replace(linkTag,()=>first?(first=false,`${api?`<link rel="preconnect" href="${api}" crossorigin>`:''}<link rel="stylesheet" href="app.bundle.css?v=${hash(css)}">`):'');
 first=true;html=html.replace(scriptTag,()=>first?(first=false,`<script src="app.bundle.js?v=${hash(js)}"></script>`):'');
 return {'index.html':html,'app.bundle.css':css,'app.bundle.js':js};
}
if(process.argv[1]===fileURLToPath(import.meta.url)){
 const root=fileURLToPath(new URL('..',import.meta.url));
 for(const [name,text] of Object.entries(build(root))){writeFileSync(root+name,text);console.log(`${name} ${text.length} bytes`);}
}
